"""Export report rows as CSV."""
import csv

HEADER = ["date", "region", "total"]


def export(rows, path, delimiter=","):
    with open(path, "w", newline="") as f:
        writer = csv.writer(f, delimiter=delimiter)
        writer.writerow(HEADER)
        writer.writerows(rows)
PRECOMPACTFIXTURE
